    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 54-year-old patient presents with a slowly worsening ache in the pelvis. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Wide surgical resection", "Radiofrequency ablation", "Systemic chemotherapy", "High-dose radiation therapy", "Denosumab therapy"]'::jsonb, 0, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 6-year-old patient presents with rapid swelling of the pelvis. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Pus settling from an abscess", "Fat floating on water within a lipoma", "Contrast pooling in a hemangioma", "Separation of cellular blood components from serum", "Necrotic tumor debris"]'::jsonb, 3, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 26-year-old patient has intense nocturnal pain in the pelvis that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Cryoablation without imaging", "Radiation therapy", "Open en bloc resection", "Intra-articular steroid injection", "CT-guided radiofrequency ablation (RFA)"]'::jsonb, 4, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 76-year-old patient complains of severe pain in the tibia. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Ischemic necrosis of the medullary cavity", "Direct mechanical pressure from the tumor mass", "Deposition of amyloid protein in the bone matrix", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Osteoblast overactivation"]'::jsonb, 3, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 80-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["Increased uptake exclusively in the appendicular skeleton", "A ''superscan'' with absent renal visualization", "Diffuse periosteal uptake", "A falsely negative (''cold'' or normal) bone scan", "Intensely increased uptake (''hot'' spots) in all lesions"]'::jsonb, 3, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'A 14-year-old male presents with deep, aching pain in the tibial diaphysis that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Radiofrequency ablation (RFA)", "Curettage and bone grafting", "Chemotherapy followed by limb-salvage surgery", "Intravenous bisphosphonates", "Radiation therapy"]'::jsonb, 0, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 14-year-old patient presents with chronic, dull knee pain. Radiographs reveal a well-demarcated, small lytic lesion exclusively located within the epiphysis of the proximal tibia. Biopsy shows ''chicken-wire'' calcifications and mononuclear cells. What is the most likely diagnosis?', '["Giant Cell Tumor", "Osteosarcoma", "Chondromyxoid fibroma", "Chondroblastoma", "Enchondroma"]'::jsonb, 3, 'Chondroblastoma is a rare, benign cartilage-forming tumor that characteristically occurs in the epiphysis (or apophysis) of long bones in skeletally immature patients (unlike Giant Cell Tumors, which usually occur after physeal closure). Histology classically shows ''''chicken-wire'''' calcifications.'),
    (v_topic_id, 'A 18-year-old patient has intense nocturnal pain in the femur that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Cryoablation without imaging", "Intra-articular steroid injection", "CT-guided radiofrequency ablation (RFA)", "Open en bloc resection", "Radiation therapy"]'::jsonb, 2, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 45-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal femur. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Curative resection of the tumor with wide margins", "Delaying surgery until radiation therapy is completed", "Achieving a biologic union of the fracture site without cement", "Immediate pain relief, early mobilization, and restoration of function", "Preventing pulmonary metastasis"]'::jsonb, 3, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 9-year-old patient has intense nocturnal pain in the radius that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Open en bloc resection", "Radiation therapy", "Cryoablation without imaging", "CT-guided radiofrequency ablation (RFA)", "Intra-articular steroid injection"]'::jsonb, 3, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 27-year-old patient has intense nocturnal pain in the humerus that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["CT-guided radiofrequency ablation (RFA)", "Open en bloc resection", "Intra-articular steroid injection", "Cryoablation without imaging", "Radiation therapy"]'::jsonb, 0, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 13-year-old presents with a painful, enlarging mass around the proximal humerus. Radiographs reveal a destructive, mixed lytic and blastic lesion in the metaphysis, with a ''sunburst'' periosteal reaction and a Codman triangle. A biopsy shows malignant cells producing unmineralized osteoid. Which of the following is the standard treatment protocol?', '["Curettage, phenol adjuvant, and cementation", "Neoadjuvant chemotherapy, surgical resection, and adjuvant chemotherapy", "Primary radiation therapy followed by resection", "Surgical resection alone", "Neoadjuvant radiation and chemotherapy without surgery"]'::jsonb, 1, 'Osteosarcoma is the most common primary bone malignancy in adolescents. It typically occurs in the metaphysis of long bones. Histologic hallmark is the production of osteoid by malignant cells. Standard treatment is neoadjuvant (preoperative) chemotherapy, wide surgical resection (limb salvage), followed by adjuvant chemotherapy based on tumor necrosis rate.'),
    (v_topic_id, 'A 56-year-old patient complains of severe pain in the humerus. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Direct mechanical pressure from the tumor mass", "Deposition of amyloid protein in the bone matrix", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Ischemic necrosis of the medullary cavity", "Osteoblast overactivation"]'::jsonb, 2, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 12-year-old patient presents with chronic, dull knee pain. Radiographs reveal a well-demarcated, small lytic lesion exclusively located within the epiphysis of the proximal tibia. Biopsy shows ''chicken-wire'' calcifications and mononuclear cells. What is the most likely diagnosis?', '["Chondroblastoma", "Giant Cell Tumor", "Chondromyxoid fibroma", "Osteosarcoma", "Enchondroma"]'::jsonb, 0, 'Chondroblastoma is a rare, benign cartilage-forming tumor that characteristically occurs in the epiphysis (or apophysis) of long bones in skeletally immature patients (unlike Giant Cell Tumors, which usually occur after physeal closure). Histology classically shows ''''chicken-wire'''' calcifications.'),
